package com.selimhorri.app.service.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.time.LocalDateTime;

import com.selimhorri.app.domain.Cart;
import com.selimhorri.app.domain.Order;
import com.selimhorri.app.dto.CartDto;
import com.selimhorri.app.dto.OrderDto;
import com.selimhorri.app.repository.OrderRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class OrderServiceImplTest {
    @Mock private OrderRepository orderRepository;
    @InjectMocks private OrderServiceImpl orderService;

    @Test
    // GreyTest trace: save | DTO converted, repository saves, saved entity mapped to DTO | BR-019 -> TP-007 -> TC-1410
    void save_mapsAndReturnsPersistedOrder() {
        // Arrange
        LocalDateTime date = LocalDateTime.parse("2025-03-08T10:15:30");
        OrderDto input = OrderDto.builder().orderId(null).orderDate(date).orderDesc("Đơn hàng mới").orderFee(25.5).cartDto(CartDto.builder().cartId(31).build()).build();
        when(orderRepository.save(any(Order.class))).thenAnswer(invocation -> {
            Order entity = invocation.getArgument(0);
            entity.setOrderId(501);
            return entity;
        });

        // Act
        OrderDto result = orderService.save(input);

        // Assert
        assertEquals(501, result.getOrderId());
        assertEquals(date, result.getOrderDate());
        assertEquals("Đơn hàng mới", result.getOrderDesc());
        assertEquals(Double.valueOf(25.5), result.getOrderFee());
        assertEquals(31, result.getCartDto().getCartId());
        ArgumentCaptor<Order> captor = ArgumentCaptor.forClass(Order.class);
        verify(orderRepository).save(captor.capture());
        assertEquals(null, captor.getValue().getOrderId());
        assertEquals(31, captor.getValue().getCart().getCartId());
    }
}
